import * as FileSystem from "expo-file-system/legacy";
import { ownPickedMedia, releasePickedMedia, withPickedMediaRead } from "./mediaPickerResources";

/** Only call with a fresh destination generated by our upload preparer. The
 * source remains caller-owned; neither a URI prefix nor caller file metadata
 * authorizes deleting it. A copy timeout is not proof the native writer stopped.
 */
export async function prepareMediaUploadCopy(input: {
  sourceUri: string;
  destinationUri: string;
  waitForCopy: (copy: Promise<void>) => Promise<void>;
}): Promise<{ uri: string; cleanup: () => Promise<void> }> {
  const prepared = { uri: input.destinationUri };
  ownPickedMedia(prepared, async () => {
    await FileSystem.deleteAsync(prepared.uri, { idempotent: true });
  });
  const cleanup = () => releasePickedMedia(prepared);
  try {
    // The exact destination lease protects the native writer and later upload
    // readers. If the source is also owned, protect it without releasing its
    // caller ownership. Both leases surround the raw copy, inside the timeout.
    await input.waitForCopy(withPickedMediaRead(prepared.uri, () =>
      withPickedMediaRead(input.sourceUri, () => FileSystem.copyAsync({
        from: input.sourceUri,
        to: prepared.uri,
      })),
    ));
    return { uri: prepared.uri, cleanup };
  } catch (error) {
    // This requests cleanup immediately, but the registry defers deletion until
    // the actual native writer settles. Preserve the copy/timeout error.
    await cleanup();
    throw error;
  }
}
